import { q, mc } from './library-expansion-model.js';

// Esborrany d'autoria: pendent de revisió editorial independent.
const e = (paragraph, es, ca) => [[paragraph, es, ca]];
const ask = (type, lines, prompt, answer, evidence, options, correct, choicePrompt = null) =>
  q(type, lines, prompt, answer, evidence, mc(options, correct, choicePrompt, answer));
const summarize = (lines, openPrompt, choicePrompt, answer, evidence, options, correct) =>
  ask('summary', lines, openPrompt, answer, evidence, options, correct, choicePrompt);

const rainA = [
  ['El viernes, la lluvia golpeaba la ventana verde con arco de la biblioteca de las cosas. En aquel local vecinal se prestaban objetos para usarlos unos días. Rosa, la coordinadora, preparaba las salidas del fin de semana. Noa y Adil, dos adolescentes que colaboraban allí, la ayudaban a reunir juegos, mantas y una carpa plegada.', 'Divendres, la pluja repicava a la finestra verda amb arc de la biblioteca de les coses. En aquell local veïnal es deixaven objectes per fer-los servir uns dies. La Rosa, la coordinadora, preparava les sortides del cap de setmana. La Noa i l’Adil, dos adolescents que hi col·laboraven, l’ajudaven a reunir jocs, mantes i una carpa plegada.'],
  ['La carpa debía cubrir una merienda en el patio del centro cívico. En otra calle, una asociación había pedido dos mantas para sentarse en el suelo durante una sesión de cuentos. Adil colocó cada objeto junto a su bolsa de transporte. Desde la puerta, las dos montañas parecían equipajes para viajar a países distintos.', 'La carpa havia de cobrir un berenar al pati del centre cívic. En un altre carrer, una associació havia demanat dues mantes per seure a terra durant una sessió de contes. L’Adil va posar cada objecte al costat de la seva bossa de transport. Des de la porta, les dues muntanyes semblaven equipatges per viatjar a països diferents.'],
  ['Al mediodía llamó la responsable de la merienda. El patio tenía charcos y habían conseguido una sala interior con mesas. Ya no necesitaban la carpa, pero querían juegos para quienes llegaran pronto. Noa sugirió mandarles también las mantas. Rosa preguntó primero si en aquella sala había sillas: la respuesta fue que sí, de sobra.', 'Al migdia va trucar la responsable del berenar. El pati tenia bassals i havien aconseguit una sala interior amb taules. Ja no necessitaven la carpa, però volien jocs per a qui arribés aviat. La Noa va suggerir enviar-los també les mantes. La Rosa va preguntar primer si en aquella sala hi havia cadires: la resposta va ser que sí, de sobres.'],
  ['Las mantas siguieron destinadas a los cuentos. Rosa llamó a las dos responsables y concretó qué recogería cada una. Para la merienda añadió un dominó grande que estaba disponible. Rosa guardó la bolsa de la carpa con otro adulto. Noa los miraba mientras el bulto dejaba libre el paso. «Menos mal que todavía no había salido», dijo.', 'Les mantes van continuar destinades als contes. La Rosa va trucar a totes dues responsables i va concretar què recolliria cadascuna. Per al berenar va afegir un dòmino gran que estava disponible. La Rosa va desar la bossa de la carpa amb un altre adult. La Noa els mirava mentre el paquet deixava lliure el pas. «Sort que encara no havia sortit», va dir.'],
  ['El sábado, Adil acompañó a su madre a la sesión de cuentos. Las mantas estaban extendidas sobre una alfombra delgada; cerca, varias familias se quitaban los zapatos. Por la tarde, una fotografía de la merienda mostró el dominó sobre una mesa. Rosa recibió la imagen en el teléfono del local y la enseñó a Noa cuando coincidieron para cerrar juntas.', 'Dissabte, l’Adil va acompanyar la seva mare a la sessió de contes. Les mantes estaven esteses damunt d’una catifa prima; a prop, diverses famílies es treien les sabates. A la tarda, una fotografia del berenar va mostrar el dòmino damunt d’una taula. La Rosa va rebre la imatge al telèfon del local i la va ensenyar a la Noa quan van coincidir per tancar juntes.'],
  ['El lunes devolvieron el dominó y las mantas secas. La bolsa de la carpa seguía en el estante. Noa la miró y sonrió: durante todo el fin de semana, aquel enorme paquete había sido el único que no había viajado.', 'Dilluns van retornar el dòmino i les mantes seques. La bossa de la carpa continuava al prestatge. La Noa se la va mirar i va somriure: durant tot el cap de setmana, aquell paquet enorme havia estat l’únic que no havia viatjat.'],
];
const rain = [
  ['El viernes, en la biblioteca de las cosas, los paraguas abiertos ocupaban casi tanto suelo como los objetos preparados para salir. El servicio vecinal prestaba herramientas, juegos y otros enseres de uso ocasional. Rosa, su coordinadora, repasaba las recogidas del fin de semana. Noa y Adil, adolescentes que colaboraban en el local, buscaban las bolsas de transporte sin pisar los regueros de agua de la entrada.', 'Divendres, a la biblioteca de les coses, els paraigües oberts ocupaven gairebé tant de terra com els objectes preparats per sortir. El servei veïnal deixava eines, jocs i altres estris d’ús ocasional. La Rosa, la coordinadora, repassava les recollides del cap de setmana. La Noa i l’Adil, adolescents que col·laboraven al local, buscaven les bosses de transport sense trepitjar els regalims d’aigua de l’entrada.'],
  ['Había dos destinos distintos. Una carpa plegable debía cubrir la merienda de un grupo de vecinos en el patio del centro cívico. Dos mantas viajarían a una sesión de cuentos en la asociación de otra calle, donde las familias se sentarían en el suelo. Noa puso las bolsas separadas y bromeó con que les faltaban billetes de tren. Rosa dejó el transporte y el montaje de la carpa en manos de los adultos de la merienda.', 'Hi havia dos destins diferents. Una carpa plegable havia de cobrir el berenar d’un grup de veïns al pati del centre cívic. Dues mantes viatjarien a una sessió de contes a l’associació d’un altre carrer, on les famílies seurien a terra. La Noa va posar les bosses separades i va fer broma que els faltaven bitllets de tren. La Rosa va deixar el transport i el muntatge de la carpa en mans dels adults del berenar.'],
  ['Al mediodía llamó Clara, la responsable de la merienda. Los charcos hacían incómodo el patio, pero el centro había conseguido una sala con mesas y sillas. La carpa dejaba de ser útil. En cambio, Clara preguntó si había algún juego para los primeros invitados, que solían llegar antes de que estuviera lista la comida. El cambio de espacio había cambiado también su petición.', 'Al migdia va trucar la Clara, la responsable del berenar. Els bassals feien incòmode el pati, però el centre havia aconseguit una sala amb taules i cadires. La carpa deixava de ser útil. En canvi, la Clara va preguntar si hi havia algun joc per als primers convidats, que solien arribar abans que el menjar estigués a punt. El canvi d’espai havia canviat també la seva petició.'],
  ['Adil recordó las mantas que esperaban junto a la puerta: podrían servir para jugar sentados. Rosa le pasó el teléfono para que escuchara a Clara explicar la sala. Tenían bastantes sillas y preferían mantener libres los pasillos. «Pues las mantas se quedan con los cuentos», respondió él. Noa encontró un dominó grande, sin otra salida prevista, y abrió la caja para mostrar sus piezas.', 'L’Adil va recordar les mantes que esperaven vora la porta: podrien servir per jugar asseguts. La Rosa li va passar el telèfon perquè sentís la Clara explicar la sala. Tenien prou cadires i preferien mantenir lliures els passadissos. «Doncs les mantes es queden amb els contes», va respondre ell. La Noa va trobar un dòmino gran, sense cap altra sortida prevista, i va obrir la caixa per mostrar-ne les peces.'],
  ['Rosa confirmó el nuevo préstamo con Clara y avisó a la responsable de los cuentos de que sus mantas seguían preparadas. Después cambió la anotación de la merienda. La carpa volvió al estante antes de que llegara la furgoneta que debía recogerla. En su lugar salió una caja que cabía bajo un brazo. El conductor tuvo que reírse al ver el espacio vacío que había dejado en el vehículo.', 'La Rosa va confirmar el nou préstec amb la Clara i va avisar la responsable dels contes que les seves mantes continuaven preparades. Després va canviar l’anotació del berenar. La carpa va tornar al prestatge abans que arribés la furgoneta que l’havia de recollir. En lloc seu va sortir una caixa que cabia sota un braç. El conductor va riure en veure l’espai buit que havia deixat al vehicle.'],
  ['El sábado, Adil fue a los cuentos con su madre y vio las mantas sobre una alfombra fina. Los pequeños se habían sentado cerca de la narradora. Por la tarde llegó al teléfono del local una fotografía de la merienda: varias manos rodeaban el dominó sobre una mesa. La ventana del fondo estaba cubierta de gotas. Rosa enseñó la foto a Noa cuando coincidieron al cerrar.', 'Dissabte, l’Adil va anar als contes amb la seva mare i va veure les mantes damunt d’una catifa prima. Els petits s’havien assegut a prop de la narradora. A la tarda va arribar al telèfon del local una fotografia del berenar: diverses mans envoltaven el dòmino sobre una taula. La finestra del fons estava coberta de gotes. La Rosa va ensenyar la foto a la Noa quan van coincidir en tancar.'],
  ['El lunes regresaron los objetos prestados. La carpa seguía quieta bajo el estante de madera color miel, pero ya no bloqueaba el paso. «Esta ha hecho turismo de interior», dijo Noa señalando el recorrido de dos metros entre el mostrador y su sitio.', 'Dilluns van tornar els objectes prestats. La carpa continuava quieta sota el prestatge de fusta mel, però ja no barrava el pas. «Aquesta ha fet turisme d’interior», va dir la Noa assenyalant el recorregut de dos metres entre el taulell i el seu lloc.'],
];
const rainB = [
  ['El viernes, la biblioteca de las cosas olía a paraguas mojado. A través de la ventana verde con arco apenas se distinguía la acera. Aquel servicio de una asociación vecinal prestaba objetos de uso ocasional: desde juegos hasta material para encuentros. Rosa, la adulta que lo coordinaba, repasaba las salidas del fin de semana. Noa y Adil, adolescentes colaboradores, habían apartado dos bolsas y una caja enorme de carpa plegable. Cada paquete tenía un destino que parecía bastante claro al comenzar la mañana.', 'Divendres, la biblioteca de les coses feia olor de paraigua moll. A través de la finestra verda amb arc amb prou feines es distingia la vorera. Aquell servei d’una associació veïnal deixava objectes d’ús ocasional: des de jocs fins a material per a trobades. La Rosa, l’adulta que el coordinava, repassava les sortides del cap de setmana. La Noa i l’Adil, adolescents col·laboradors, havien apartat dues bosses i una caixa enorme de carpa plegable. Cada paquet tenia un destí que semblava força clar al començament del matí.'],
  ['La carpa iría a la merienda de unos vecinos en el patio del centro cívico. Los adultos organizadores se encargarían de llevarla y montarla. Las bolsas contenían mantas para una sesión de cuentos en la asociación de otra calle. Allí se sentarían en el suelo, sobre una alfombra fina. Adil dibujó en un papel dos flechas para no mezclar las recogidas. Noa añadió una nube sobre las dos, aunque los cuentos se celebraban dentro desde el principio.', 'La carpa aniria al berenar d’uns veïns al pati del centre cívic. Els adults organitzadors s’encarregarien de portar-la i muntar-la. Les bosses contenien mantes per a una sessió de contes a l’associació d’un altre carrer. Allà seurien a terra, sobre una catifa prima. L’Adil va dibuixar en un paper dues fletxes per no barrejar les recollides. La Noa va afegir-hi un núvol sobre totes dues, tot i que els contes es feien a dins des del principi.'],
  ['A mediodía, Clara, responsable de la merienda, llamó para cambiar la petición. El patio estaba lleno de charcos. El centro les había ofrecido una sala con mesas y sillas, de modo que la carpa sobraba. Sin embargo, la gente llegaría a la misma hora y la comida aún tardaría un rato en estar lista. Clara preguntó por juegos que pudieran ponerse sobre las mesas. Rosa la escuchó mientras miraba la caja de la carpa, que todavía seguía junto al mostrador.', 'Al migdia, la Clara, responsable del berenar, va trucar per canviar la petició. El pati era ple de bassals. El centre els havia ofert una sala amb taules i cadires, de manera que la carpa sobrava. Tanmateix, la gent arribaria a la mateixa hora i el menjar encara trigaria una estona a estar a punt. La Clara va preguntar per jocs que es poguessin posar sobre les taules. La Rosa la va escoltar mentre mirava la caixa de la carpa, que encara continuava vora el taulell.'],
  ['Noa apuntó hacia las mantas: quizá servirían para hacer un rincón de juegos. Rosa le pidió que preguntara por el espacio antes de moverlas. Clara explicó por el altavoz que las mesas ocuparían casi toda la sala y convenía dejar los pasillos despejados. Además, ya tenían sillas suficientes. Noa borró su primer dibujo de un rincón en el suelo. Adil encontró un dominó grande disponible y levantó la caja para que Rosa pudiera verla desde el teléfono.', 'La Noa va assenyalar les mantes: potser servirien per fer un racó de jocs. La Rosa li va demanar que preguntés per l’espai abans de moure-les. La Clara va explicar per l’altaveu que les taules ocuparien gairebé tota la sala i convenia deixar els passadissos lliures. A més, ja tenien prou cadires. La Noa va esborrar el seu primer dibuix d’un racó a terra. L’Adil va trobar un dòmino gran disponible i va alçar la caixa perquè la Rosa la pogués veure des del telèfon.'],
  ['La solución quedó acordada con las dos responsables: las mantas mantendrían su viaje a los cuentos y el dominó acompañaría la merienda. Rosa cambió la anotación y devolvió la carpa a su estante con otro voluntario adulto. Cuando llegó la furgoneta, Clara salió con una caja bajo el brazo. El conductor abrió la puerta trasera, contempló todo el espacio preparado y volvió a cerrarla. La caja viajaría delante, sin aquel enorme volumen para el que habían movido un asiento.', 'La solució va quedar acordada amb totes dues responsables: les mantes mantindrien el viatge als contes i el dòmino acompanyaria el berenar. La Rosa va canviar l’anotació i va tornar la carpa al prestatge amb un altre voluntari adult. Quan va arribar la furgoneta, la Clara va sortir amb una caixa sota el braç. El conductor va obrir la porta del darrere, va contemplar tot l’espai preparat i la va tornar a tancar. La caixa viatjaria davant, sense aquell volum enorme per al qual havien mogut un seient.'],
  ['El sábado, Adil acompañó a su madre a los cuentos. Vio las mantas sobre la alfombra y a varias familias instalándose cerca de la narradora. Una abuela se quedó en una silla que había junto a la pared. Adil sacó una foto de las bolsas vacías para enseñársela a Noa; evitó fotografiar al público. Al salir, la lluvia continuaba y su madre tuvo que abrir el paraguas mientras él sujetaba el libro que acababan de comprar.', 'Dissabte, l’Adil va acompanyar la seva mare als contes. Va veure les mantes damunt la catifa i diverses famílies instal·lant-se a prop de la narradora. Una àvia es va quedar en una cadira que hi havia al costat de la paret. L’Adil va fer una foto de les bosses buides per ensenyar-la a la Noa; va evitar fotografiar el públic. En sortir, continuava plovent i la seva mare va haver d’obrir el paraigua mentre ell aguantava el llibre que acabaven de comprar.'],
  ['Esa tarde, Clara envió a Rosa una imagen de las manos alrededor del dominó. En un mensaje añadió que algunos habían seguido jugando después de comer. La foto mostraba el juego en la mesa, mientras que el mensaje añadía el uso después de comer. La imagen no permitía saber cuántas personas habían participado durante toda la tarde. Rosa enseñó ambos mensajes a Noa cuando llegó al local. Ella dibujó una mesa al final de una de las flechas de Adil y dejó la otra como estaba.', 'Aquella tarda, la Clara va enviar a la Rosa una imatge de les mans al voltant del dòmino. En un missatge va afegir que alguns havien continuat jugant després de menjar. La foto mostrava el joc a la taula, mentre que el missatge afegia l’ús després de menjar. La imatge no permetia saber quantes persones hi havien participat durant tota la tarda. La Rosa va ensenyar tots dos missatges a la Noa quan va arribar al local. Ella va dibuixar una taula al final d’una de les fletxes de l’Adil i va deixar l’altra com estava.'],
  ['El lunes, al recibir las mantas secas y el dominó, Rosa encontró el papel de las flechas. La nube de Noa ocupaba medio margen. La carpa seguía en casa, bajo la estantería de madera color miel, después de un recorrido de apenas dos metros.', 'Dilluns, en rebre les mantes seques i el dòmino, la Rosa va trobar el paper de les fletxes. El núvol de la Noa ocupava mig marge. La carpa continuava a casa, sota la prestatgeria de fusta mel, després d’un recorregut de tot just dos metres.'],
];

